var keys = Tama.Args.Get(args, "titles", "").Split(',').Select(s => s.Trim()).Where(s => s.Length > 0).ToList();
Func<XYZ,double[]> m = p => new[]{Math.Round(p.X*0.3048,4),Math.Round(p.Y*0.3048,4),Math.Round(p.Z*0.3048,4)};
var res = new List<object>();
var all = new List<string>();
foreach (Document d in app.Documents)
{
  all.Add(d.Title + (d.IsLinked ? " [link]" : " [open]") + (d.Title == doc.Title ? " [active]" : ""));
  if (d.IsLinked || d.IsFamilyDocument || !keys.Any(k => d.Title.Contains(k))) continue;
  var locs = new List<object>();
  foreach (ProjectLocation pl in d.ProjectLocations) {
    var pp = pl.GetProjectPosition(XYZ.Zero);
    locs.Add(new { name = pl.Name, id = pl.Id.IntegerValue, active = d.ActiveProjectLocation.Id == pl.Id,
      ew = Math.Round(pp.EastWest*0.3048,4), ns = Math.Round(pp.NorthSouth*0.3048,4), elev = Math.Round(pp.Elevation*0.3048,4), angle = Math.Round(pp.Angle*180/Math.PI,6) });
  }
  var bps = new FilteredElementCollector(d).OfClass(typeof(BasePoint)).Cast<BasePoint>().Select(b => new { survey = b.IsShared, internal_m = m(b.Position), shared_m = m(b.SharedPosition), pinned = b.Pinned }).ToList();
  var links = new FilteredElementCollector(d).OfClass(typeof(RevitLinkInstance)).Cast<RevitLinkInstance>().Where(li => li.Name.Contains("000000")).Select(li => {
    var t = li.GetTransform();
    return new { id = li.Id.IntegerValue, name = li.Name, pinned = li.Pinned, origin_m = m(t.Origin), rot = Math.Round(Math.Atan2(t.BasisX.Y,t.BasisX.X)*180/Math.PI,6),
      owner = d.IsWorkshared ? WorksharingUtils.GetCheckoutStatus(d, li.Id).ToString() : "n/a" };
  }).ToList();
  res.Add(new { title = d.Title, path = d.PathName, workshared = d.IsWorkshared, locations = locs, basePoints = bps, siteLinks = links });
}
return new { active = doc.Title, docs = all, matches = res };
